const today = new Date();
const dayIndex = today.getDay();

const getWeekNumber = (d) => {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const dayNum = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
};
const weekNum = getWeekNumber(today);
const isOddWeek = weekNum % 2 !== 0;

// Mon/Thu/Sun posts — 2 alternating content types per day
const configMap = {
  1: isOddWeek
    ? {
        category: 'The Villa',
        postType: 'property',
        topic: 'The 4-level Moroccan-inspired villa — pool terrace, rooftop sky bed, glass accordion doors, sea views, Baja desert backdrop. A design that stops people mid-scroll.',
        audience: 'Luxury travelers, architecture enthusiasts, design-conscious renters',
        postStyle: 'Visual, architectural, sensory — make the property feel cinematic',
        ctaStyle: 'Book at themoroccanpalace.com',
        hookExample: 'Four levels. A 22-foot pool. The Sea of Cortez in every direction.',
        pexelsQuery: 'luxury villa pool rooftop terrace Mexico Baja ocean view'
      }
    : {
        category: 'Kite & Adventure',
        postType: 'adventure',
        topic: 'La Ventana kite school 5 minutes from the property — world-class consistent Baja winds, all levels, Sea of Cortez, desert mountains behind you.',
        audience: 'Kite surfers, wind sports enthusiasts, adventure travelers',
        postStyle: 'Energetic, kinetic, wind and water imagery',
        ctaStyle: 'Stay at The Moroccan Palace, kite from La Ventana — themoroccanpalace.com',
        hookExample: 'The wind starts at 9am. The kite school is 5 minutes south.',
        pexelsQuery: 'kite surfing Mexico Pacific Baja wind adventure beach'
      },
  4: isOddWeek
    ? {
        category: 'Glamping',
        postType: 'glamping',
        topic: 'The 3 luxury glamping tents — soft rugs, ambient lighting, outdoor showers, desert stars. A different way to experience Baja.',
        audience: 'Glamping lovers, festival-style travelers, groups with mixed accommodation preferences',
        postStyle: 'Dreamy, sensory, softly adventurous',
        ctaStyle: 'Glamping available — themoroccanpalace.com',
        hookExample: 'The tent was silk rugs and warm light. Outside: silence and a sky full of stars.',
        pexelsQuery: 'luxury glamping tent desert stars night sky outdoor ambient'
      }
    : {
        category: 'Baja & Destination',
        postType: 'destination',
        topic: 'El Sargento and La Ventana — Sea of Cortez, Sierra de la Laguna mountains, Baja light, the raw beauty of the destination itself.',
        audience: 'Baja explorers, Sea of Cortez travelers, destination seekers',
        postStyle: 'Landscape-driven, evocative of raw Baja beauty',
        ctaStyle: 'Make The Moroccan Palace your Baja base — themoroccanpalace.com',
        hookExample: 'The Sea of Cortez from the terrace. The Sierra behind you. Baja at its best.',
        pexelsQuery: 'Baja California Mexico Sea of Cortez beach sunset mountains landscape'
      },
  0: isOddWeek
    ? {
        category: 'Wellness',
        postType: 'wellness',
        topic: 'Jewels — 25 years of therapeutic massage and acupuncture, on the terrace overlooking the sea. Yoga. Sound healing. A wellness stay unlike any resort.',
        audience: 'Wellness seekers, burned-out professionals, retreat planners',
        postStyle: 'Quiet, restorative, intentional — slow luxury',
        ctaStyle: 'Wellness stays available — themoroccanpalace.com',
        hookExample: 'The massage was on the terrace. The sea was in front. Nothing else needed.',
        pexelsQuery: 'wellness massage yoga meditation spa terrace ocean luxury Mexico'
      }
    : {
        category: 'Events & Celebrations',
        postType: 'events',
        topic: 'Weddings, bachelorettes, milestone birthdays, corporate retreats — the villa as a private venue with the Sea of Cortez as the backdrop.',
        audience: 'Event planners, couples, celebration groups',
        postStyle: 'Celebratory, intimate, emotionally rich',
        ctaStyle: 'Inquire about events — themoroccanpalace.com',
        hookExample: 'A rooftop ceremony. The Sea of Cortez at golden hour. Your whole group together.',
        pexelsQuery: 'luxury outdoor wedding celebration terrace rooftop Mexico desert'
      }
};

const cfg = configMap[dayIndex] || configMap[1];

return [{
  json: {
    dayIndex,
    dayName: ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][dayIndex],
    runDate: today.toISOString().split('T')[0],
    weekNum,
    category: cfg.category,
    postType: cfg.postType,
    topic: cfg.topic,
    audience: cfg.audience,
    postStyle: cfg.postStyle,
    ctaStyle: cfg.ctaStyle,
    hookExample: cfg.hookExample,
    pexelsQuery: cfg.pexelsQuery
  }
}];

const pexelsResp = $input.first().json;
const dayConfig = $('Get Day Config').first().json;

const photos = pexelsResp.photos || [];
if (photos.length === 0) {
  throw new Error('Pexels returned no photos for query: ' + dayConfig.pexelsQuery);
}

const shuffled = [...photos].sort(() => Math.random() - 0.5);
const selected = shuffled.slice(0, Math.min(3, shuffled.length));

return selected.map((photo, idx) => ({
  json: {
    photoIndex: idx,
    cdnUrl: photo.src.large2x || photo.src.large || photo.src.original,
    pexelsId: photo.id,
    photographer: photo.photographer,
    postType: dayConfig.postType,
    dayIndex: dayConfig.dayIndex,
    dayName: dayConfig.dayName,
    runDate: dayConfig.runDate,
    category: dayConfig.category,
    topic: dayConfig.topic,
    audience: dayConfig.audience,
    postStyle: dayConfig.postStyle,
    ctaStyle: dayConfig.ctaStyle,
    hookExample: dayConfig.hookExample
  }
}));

const uploads = $input.all();
const originalPhotos = $('Pick 3 Photos').all();
const dayConfig = $('Get Day Config').first().json;

if (uploads.length === 0) {
  throw new Error('No photos uploaded to Facebook. Check page token and permissions.');
}

const fbPhotoIds = uploads.map(item => item.json.id || item.json.photo_id);
const cdnUrls = originalPhotos.map(item => item.json.cdnUrl);

return [{
  json: {
    fbPhotoIds,
    cdnUrls,
    photoCount: fbPhotoIds.length,
    dayIndex: dayConfig.dayIndex,
    dayName: dayConfig.dayName,
    runDate: dayConfig.runDate,
    category: dayConfig.category,
    postType: dayConfig.postType,
    topic: dayConfig.topic,
    audience: dayConfig.audience,
    postStyle: dayConfig.postStyle,
    ctaStyle: dayConfig.ctaStyle,
    hookExample: dayConfig.hookExample
  }
}];

const item = $input.first();
const prevData = $('Collect Upload Results').first().json;

let postText = '';
if (item.json.content && Array.isArray(item.json.content) && item.json.content.length > 0) {
  postText = item.json.content[0].text || '';
}
if (!postText.trim()) {
  throw new Error('Claude returned empty post text. Check API key and request format.');
}

const wordCount = postText.trim().split(/\s+/).length;
const warnings = [];
if (wordCount < 60) warnings.push(`Post short: ${wordCount} words`);
if (wordCount > 280) warnings.push(`Post long: ${wordCount} words`);
if (/\*\*|\*[^*]/.test(postText)) warnings.push('Markdown detected');

return [{
  json: {
    postText: postText.trim(),
    wordCount,
    warnings: warnings.join(' | ') || 'None',
    fbPhotoIds: prevData.fbPhotoIds,
    cdnUrls: prevData.cdnUrls,
    dayName: prevData.dayName,
    audience: prevData.audience,
    runDate: prevData.runDate,
    category: prevData.category
  }
}];

const item = $input.first();
const fbPostBody = {
  message: item.json.postText,
  attached_media: item.json.fbPhotoIds.map(id => ({ media_fbid: id })),
  published: true
};
return [{ json: { ...item.json, fbPostBodyJson: JSON.stringify(fbPostBody) } }];

const errorData = $input.first().json;
console.error('Moroccan Palace workflow error:', JSON.stringify({
  date: new Date().toISOString(),
  workflow: 'The Moroccan Palace — Daily Social Post',
  error: errorData.error && errorData.error.message,
  node: errorData.error && errorData.error.node && errorData.error.node.name,
  executionId: errorData.execution && errorData.execution.id
}));
return $input.all();
